import {completedStage} from './journeys.js';
import {ensureLevels,levelProgress,isPast} from './levels.js';
import {WORLDS} from './worlds.js';
export const DEFAULT_POLICY={pastCrystals:.1,pastXP:.2,replayBonus:.25,dailyCrystals:900,dailyXP:4000,minimum:0};
export function policy(p){return {...DEFAULT_POLICY,...p.rewardPolicy};}
export function rewardStatus(p,pack){const past=isPast(p,pack);return {past,crystals:past?policy(p).pastCrystals:1,xp:past?policy(p).pastXP:1,replay:levelProgress(p,pack.id).completed};}
export function queueReward(r,kind,crystals,xp,key){r.sessionId??='legacy-'+r.seed+'-'+r.packId+'-'+r.theme;r.rewardEvents??=[];const id=r.sessionId+':'+key;if(r.rewardEvents.some(e=>e.id===id))return;r.rewardEvents.push({id,kind,crystals,xp,stage:r.stage});r.crystals+=crystals;r.petXP=(r.petXP||0)+xp;}
// The ledger belongs to the profile, outside a course snapshot. Rewinding that
// snapshot cannot rewind its paid cursors or repeat its event IDs.
export function settleRewards(p,r,pack,day=new Date().toISOString().slice(0,10)){
 ensureLevels(p);const cfg=policy(p),state=rewardStatus(p,pack),pr=levelProgress(p,pack.id);r.sessionId??='legacy-'+r.seed+'-'+r.packId+'-'+r.theme;
 const ledger=p.rewardBook.runs[r.sessionId]??={rawCrystals:r.bankedCrystals||0,rawXP:r.bankedXP||0,events:[],bonusCrystals:0,bonusXP:0,trackCrystals:r.bankedCrystals||0,trackXP:r.bankedXP||0};
 const daily=p.rewardBook.days[day]??={crystals:0,xp:0};let coins=0,xp=0;
 const pay=(c,x,kind,stage)=>{const repeated=state.replay||(kind==='stage'&&pr.worlds[r.theme]?.stageIds?.includes(stage));const repeat=!state.past&&repeated&&['stage','explore','gate'].includes(kind)?cfg.replayBonus:1;const cr=state.past?cfg.pastCrystals:repeat,xr=state.past?cfg.pastXP:1;const rawC=pr.dust+c*cr,rawX=pr.xpDust+x*xr;let a=Math.floor(rawC+1e-9),b=Math.floor(rawX+1e-9);pr.dust=Math.max(0,rawC-a);pr.xpDust=Math.max(0,rawX-b);if(c>0&&kind!=='track')a=Math.max(a,Math.min(cfg.minimum,Math.floor(c)));a=Math.min(a,Math.max(0,cfg.dailyCrystals-daily.crystals));b=Math.min(b,Math.max(0,cfg.dailyXP-daily.xp));daily.crystals+=a;daily.xp+=b;coins+=a;xp+=b;};
 const events=r.rewardEvents||[],totalC=events.reduce((n,e)=>n+e.crystals,0),totalX=events.reduce((n,e)=>n+e.xp,0);
 const rawTrack=Math.max(0,r.crystals-totalC),rawTrackXP=Math.max(0,(r.petXP||0)-totalX);
 const prevTrack=ledger.trackCrystals,prevXP=ledger.trackXP;
 pay(Math.max(0,rawTrack-prevTrack),Math.max(0,rawTrackXP-prevXP)+Math.max(0,rawTrack-prevTrack),'track');
 for(const event of events)if(!ledger.events.includes(event.id)){ledger.events.push(event.id);ledger.bonusCrystals+=event.crystals;ledger.bonusXP+=event.xp;pay(event.crystals,event.xp,event.kind,event.stage);if(event.kind==='stage'){completedStage(p,r.gameMode||'runner',r.theme,event.stage);if(p.collection){const totals=p.collection.worlds[r.theme]??={stages:0,finishes:0};totals.stages++;if([0,1,2].every(n=>n===event.stage||pr.worlds[r.theme]?.stageIds?.includes(n))&&pr.worlds[r.theme]?.stageIds?.length!==3)totals.finishes++;}p.rewards.push({id:event.id,title:WORLDS[r.theme].stages[event.stage]+' Crystal',date:new Date().toISOString(),kind:'stage'});const w=pr.worlds[r.theme]??={stages:0,finishes:0,bestScore:0,stageIds:[]};w.stageIds??=[];if(!w.stageIds.includes(event.stage))w.stageIds.push(event.stage);w.stages++;w.bestScore=Math.max(w.bestScore,Math.floor(r.score));if(w.stageIds.length===3){w.finishes=Math.max(1,w.finishes);pr.completed=true;}const badge=r.packId+'~'+r.theme;if(!p.rewards.some(x=>x.id===badge)&&w.stageIds.length===3){p.rewards.push({id:badge,title:WORLDS[r.theme].name+' level completion badge',date:new Date().toISOString()});if(p.collection){const cosmetic={volcano:'cap',cosmic:'pendant',jungle:'collar',underwater:'trail',castle:'cape',haunted:'aura',frozen:'scarf'}[r.theme];if(!p.collection.accessories.includes(cosmetic))p.collection.accessories.push(cosmetic);}}}}
 ledger.trackCrystals=Math.max(ledger.trackCrystals,rawTrack);ledger.trackXP=Math.max(ledger.trackXP,rawTrackXP);
 ledger.rawCrystals=Math.max(ledger.rawCrystals,r.crystals);ledger.rawXP=Math.max(ledger.rawXP,r.petXP||0);r.bankedCrystals=r.crystals;r.bankedXP=r.petXP||0;r.earnedCrystals=(r.earnedCrystals||0)+coins;r.earnedXP=(r.earnedXP||0)+xp;return {coins,xp};
}
export function validRewards(p){if(p.rewardPolicy){const x=policy(p);if(![x.pastCrystals,x.pastXP,x.replayBonus].every(n=>Number.isFinite(n)&&n>=0&&n<=1)||![x.dailyCrystals,x.dailyXP,x.minimum].every(n=>Number.isSafeInteger(n)&&n>=0&&n<=100000))return false;}if(!p.rewardBook)return true;if(!p.rewardBook.runs||!p.rewardBook.days)return false;for(const r of Object.values(p.rewardBook.runs))if(!r||!Array.isArray(r.events)||r.events.some(e=>typeof e!=='string')||![r.rawCrystals,r.rawXP,r.bonusCrystals,r.bonusXP,r.trackCrystals,r.trackXP].every(n=>Number.isFinite(n)&&n>=0))return false;for(const d of Object.values(p.rewardBook.days))if(!d||![d.crystals,d.xp].every(n=>Number.isSafeInteger(n)&&n>=0))return false;return true;}
